Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  FILE *file = NULL;

  /* Validate input parameters */
  if (!image_info || !exception)
    return NULL;

  /* Open the image file */
  file = fopen(image_info->filename, "rb");
  if (!file) {
    ThrowFileException(exception, FileOpenError, image_info->filename, "PNG");
    return NULL;
  }

  /* Check for valid PNG signature */
  unsigned char signature[8];
  if (fread(signature, 1, sizeof(signature), file) != sizeof(signature) ||
      memcmp(signature, "\x89PNG\r\n\x1a\n", 8) != 0) {
    fclose(file);
    Throw(exception, CorruptImageError, "Invalid PNG signature");
    return NULL;
  }

  /* Allocate memory for MngInfo structure */
  MngInfo *mng_info = AcquireMagickMemory(sizeof(*mng_info));
  if (!mng_info) {
    fclose(file);
    Throw(exception, ResourceLimitError, "Memory allocation failed for MngInfo");
    return NULL;
  }

  /* Initialize and use MngInfo to read the PNG image data */
  InitializeMngInfo(mng_info);
  ReadPNGData(mng_info, file, &image);

  /* Check for errors during reading */
  if (!image) {
    RelinquishMagickMemory(mng_info);
    fclose(file);
    return NULL;
  }

  /* Check image dimensions and colorspace */
  if (image->columns == 0 || image->rows == 0) {
    RelinquishMagickMemory(mng_info);
    fclose(file);
    Throw(exception, CorruptImageError, "Invalid image dimensions");
    return NULL;
  }

  /* Adjust colorspace if necessary */
  if (image->colorspace != PNG_COLORSPACE)
    image->colorspace = PNG_COLORSPACE;

  /* Clean up */
  RelinquishMagickMemory(mng_info);
  fclose(file);

  return image;
}

Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image;
  FILE *file;
  MngInfo *mng_info;

  // Validate input parameters
  if (!image_info || !exception)
    return NULL;

  // Open the image file
  file = fopen(image_info->filename, "rb");
  if (!file) {
    ThrowFileException(exception, FileOpenError, "Unable to open image file", image_info->filename);
    return NULL;
  }

  // Check for valid PNG signature
  unsigned char signature[PNG_SIG_SIZE];
  if (fread(signature, PNG_SIG_SIZE, 1, file) != 1 || png_sig_cmp(signature, 0, PNG_SIG_SIZE)) {
    fclose(file);
    ThrowException(exception, CorruptImageError, "Invalid PNG signature", image_info->filename);
    return NULL;
  }

  // Allocate memory for MngInfo structure
  mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
  if (!mng_info) {
    fclose(file);
    ThrowException(exception, ResourceLimitError, "Unable to allocate memory for MngInfo", image_info->filename);
    return NULL;
  }

  // Initialize MngInfo and read PNG data
  InitializeMngInfo(mng_info);
  image = ReadPNGData(file, image_info, mng_info, exception);
  if (!image) {
    fclose(file);
    ReleaseMemory(mng_info);
    return NULL;
  }

  // Check image dimensions and adjust colorspace if needed
  if (image->columns <= 0 || image->rows <= 0) {
    DestroyImage(image);
    fclose(file);
    ThrowException(exception, CorruptImageError, "Invalid image dimensions", image_info->filename);
    return NULL;
  }

  if (image->colorspace == UndefinedColorspace)
    image->colorspace = sRGBColorspace;

  fclose(file);
  return image;
}

