  FILE *file = NULL;
  unsigned char signature[PNGSIG_MAX_LENGTH];

  assert(image_info != NULL);
  assert(exception != NULL);

  /* Open the image file */
  file = fopen(image_info->filename, "rb");
  if (file == NULL)
  {
    ThrowFileException(exception, FileOpenError, image_info->filename);
    return NULL;
  }

  /* Check for a valid PNG signature */
  if (fread(signature, 1, PNGSIG_LENGTH, file) != PNGSIG_LENGTH)
  {
    fclose(file);
    ThrowFileException(exception, CorruptImageError, "Invalid PNG signature", image_info->filename);
    return NULL;
  }

  if (png_sig_cmp(signature, 0, PNGSIG_LENGTH))
  {
    fclose(file);
    ThrowFileException(exception, CorruptImageError, "Invalid PNG signature", image_info->filename);
    return NULL;
  }

  /* Allocate memory for MngInfo structure */
  MngInfo *mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
  if (mng_info == NULL)
  {
    fclose(file);
    ThrowFileException(exception, ResourceLimitError, "Unable to allocate memory", "MngInfo structure");
    return NULL;
  }

  /* Initialize MngInfo and read the PNG image data */
  InitializeMngInfo(mng_info);
  image = ReadPNGImageInternal(file, mng_info, exception);
  if (image == NULL)
  {
    fclose(file);
    RelinquishMemory(mng_info);
    return NULL;
  }

  /* Check and adjust colorspace if necessary */
  if (image->colorspace != RGBColorspace)
    image->colorspace = RGBColorspace;

  fclose(file);

  return image;
}

Image *
ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  FILE *file;
  unsigned char signature[PNG_SIGNATURE_SIZE];
  MngInfo *mng_info;
  size_t file_size;
  ssize_t count;

  assert(image_info != (const ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  /* Open the image file */
  file = fopen(image_info->filename, "rb");
  if (file == (FILE *) NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "Unable to open file", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Check the file size */
  fseek(file, 0, SEEK_END);
  file_size = (size_t) ftell(file);
  fseek(file, 0, SEEK_SET);

  if (file_size < (size_t) PNG_SIGNATURE_SIZE)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Invalid file size", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Read the PNG signature */
  count = fread(signature, 1, PNG_SIGNATURE_SIZE, file);
  if (count != PNG_SIGNATURE_SIZE)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Unable to read PNG signature", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (!png_check(signature, PNG_SIGNATURE_SIZE))
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Invalid PNG signature", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Allocate MngInfo structure */
  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "Unable to allocate memory", "%s", image_info->filename);
    return (Image *) NULL;
  }

  (void) memset(mng_info, 0, sizeof(*mng_info));

  /* Proceed with reading the PNG data into the image structure */
  image = ReadPNGImageInternal(file, image_info, mng_info, exception);
  if (image == (Image *) NULL)
  {
    RelinquishMagickMemory(mng_info);
    (void) fclose(file);
    return (Image *) NULL;
  }

  /* Check image dimensions and colorspace */
  if (image->columns <= 0 || image->rows <= 0)
  {
    DestroyImageList(image);
    RelinquishMagickMemory(mng_info);
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Invalid image dimensions", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Adjust colorspace if needed */
  if (image->colorspace == UndefinedColorspace)
    image->colorspace = sRGBColorspace;

  (void) fclose(file);
  RelinquishMagickMemory(mng_info);

  return image;
}

